float4 node33_func(float3 WorldPos, float4 Color, float endDistance, float startDistance, float4 Pos)
{
static const float4x4 DITHER_MATRIX = float4x4(
    1.0 / 17.0,  9.0 / 17.0,  3.0 / 17.0, 11.0 / 17.0,
    13.0 / 17.0,  5.0 / 17.0, 15.0 / 17.0,  7.0 / 17.0,
    4.0 / 17.0, 12.0 / 17.0,  2.0 / 17.0, 10.0 / 17.0,
    16.0 / 17.0,  8.0 / 17.0, 14.0 / 17.0,  6.0 / 17.0
    );

    float dist = distance(g_camPos, WorldPos);

    float alpha = saturate((dist - endDistance) / (startDistance - endDistance));

    uint2 pixelPos = uint2(Pos.xy) % 4;
    float ditherValue = DITHER_MATRIX[pixelPos.x][pixelPos.y];

   clip(alpha - ditherValue);

    return Color;
}

float4 node27_func(float4 color, float saturation)
{
static const float3 LumCoeff = float3(0.2126, 0.7152, 0.0722);

float luminance = dot(color.rgb, LumCoeff);
float3 grayColor = float3(luminance, luminance, luminance);
float3 result = lerp(grayColor, color.rgb, saturation);

return float4(result, color.a);
}


struct PS_IN {
    float4 pos : SV_Position;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 viewNormal : NORMAL1;
    float3 worldNormal : NORMAL2;
    float3 worldPos : POSITION1;
    float3 worldTangent : TANGENT;
    nointerpolation uint instID : INSTANCEID;
};

struct PS_OUT {
    float4 target0 : SV_Target0;
    float4 target1 : SV_Target1;
    float4 target2 : SV_Target2;
    float4 target3 : SV_Target3;
    float4 target4 : SV_Target4;
};

PS_OUT main(PS_IN In)
{
    float3 node36_out = In.worldPos;
    float4 node6_out = (g_modelBaseColor.Sample(g_sampler, In.uv) * g_baseColorRate);
    float node28_out = 0.800000f;
    float4 node27_out = node27_func(node6_out, node28_out);
    float4 node20_out = g_params[0];
    float node21_out = 0.520000f;
    float node22_out = 0.210000f;
    float3 ssh19_N = normalize(In.worldNormal);
    float3 ssh19_T = normalize(In.worldTangent - dot(In.worldTangent, ssh19_N) * ssh19_N);
    float3 ssh19_B = cross(ssh19_N, ssh19_T);
    float3x3 ssh19_TBN = float3x3(ssh19_T, ssh19_B, ssh19_N);
    float3 ssh19_Lw = normalize(((node20_out).xyz));
    float3 ssh19_Lt = mul(ssh19_TBN, ssh19_Lw);
    float ssh19_h0 = dot(g_modelBaseColor.Sample(g_sampler, In.uv).rgb, float3(0.299,0.587,0.114));
    float ssh19_shadow = 1.0;
    float2 ssh19_uvStep = ssh19_Lt.xy * (node22_out) * 0.01;
    [unroll] for (int ssh19_i = 1; ssh19_i <= 8; ++ssh19_i)
    {
        float2 ssh19_suv = In.uv + ssh19_uvStep * ssh19_i;
        float ssh19_hs = dot(g_modelBaseColor.Sample(g_sampler, ssh19_suv).rgb, float3(0.299,0.587,0.114));
        float ssh19_expected = ssh19_h0 + ssh19_Lt.z * ssh19_i * 0.05;
        if (ssh19_hs > ssh19_expected)
            ssh19_shadow = min(ssh19_shadow, 1.0 - (ssh19_hs - ssh19_expected) * 5.0);
    }
    ssh19_shadow = saturate(lerp(1.0, ssh19_shadow, (node21_out)));
    float3 ssh19_result = (node27_out).rgb * ssh19_shadow;
    float4 node19_out = float4(ssh19_result, (node27_out).a);
    float node34_out = 0.010000f;
    float node35_out = 5.000000f;
    float4 node37_out = In.pos;
    float4 node33_out = node33_func(node36_out, node19_out, node34_out, node35_out, node37_out);
    float nfh26_str = 0.060000f;
    float3 nfh26_rawN = In.worldNormal;
    float  nfh26_lenN = length(nfh26_rawN);
    float3 nfh26_N = (nfh26_lenN > 1e-5) ? (nfh26_rawN / nfh26_lenN) : float3(0.0, 1.0, 0.0);
    float3 nfh26_rawT = In.worldTangent - dot(In.worldTangent, nfh26_N) * nfh26_N;
    float  nfh26_lenT = length(nfh26_rawT);
    float3 nfh26_fb = (abs(nfh26_N.y) < 0.99) ? float3(0.0, 1.0, 0.0) : float3(1.0, 0.0, 0.0);
    float3 nfh26_T = (nfh26_lenT > 1e-5) ? (nfh26_rawT / nfh26_lenT) : normalize(cross(nfh26_fb, nfh26_N));
    float3 nfh26_B = cross(nfh26_N, nfh26_T);
    float4 nfh26_col = node19_out;
    float nfh26_h = dot(nfh26_col.rgb, float3(0.2126, 0.7152, 0.0722)) * nfh26_str;
    float3 nfh26_dpdx = ddx(In.worldPos);
    float3 nfh26_dpdy = ddy(In.worldPos);
    float3 nfh26_R1 = cross(nfh26_dpdy, nfh26_N);
    float3 nfh26_R2 = cross(nfh26_N, nfh26_dpdx);
    float  nfh26_det = dot(nfh26_dpdx, nfh26_R1);
    float3 nfh26_grad = sign(nfh26_det) * (ddx(nfh26_h) * nfh26_R1 + ddy(nfh26_h) * nfh26_R2);
    float3 nfh26_result = normalize(abs(nfh26_det) * nfh26_N - nfh26_grad);
    float3 nfh26_texN = float3(dot(nfh26_result, nfh26_T), dot(nfh26_result, nfh26_B), dot(nfh26_result, nfh26_N));
    float3 node26_out = nfh26_result;
    float4 node23_out = float4(0.062500f, 0.059180f, 0.049219f, 1.000000f);
    float4 node29_out = float4(1.000000f, 0.000000f, 0.000000f, 1.000000f);
    float node32_out = 1.000000f;
    PS_OUT o;
    o.target0 = float4((node33_out).xyz, (g_modelMetalRough.Sample(g_sampler, In.uv).b * g_metallicRate));
    o.target1 = float4((nfh26_result) * 0.5 + 0.5, (g_modelMetalRough.Sample(g_sampler, In.uv).g * g_roughnessRate));
    o.target2 = float4(In.worldPos, 1.0);
    o.target3 = float4((node23_out).xyz, node32_out);
    o.target4 = node29_out;
    return o;
}

